package com.trafficcraft.vehicle;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import net.minecraft.world.phys.Vec3;

/** Data generated by tools/vehgen for every vehicle model (dimensions, seats, wheels, lights, dashboard, engine). */
public final class VehicleSpec {
    public record Wheel(float x, float y, float z, float r, boolean steer, boolean mirror) {}
    public record Door(String part, float hingeX, float hingeZ, int side, String kind) {}
    public record Dial(String kind, float cx, float cy, float r, float a0, float a1, float max, float x, float y, float w, float h, float size, int color) {}

    public final String id, name, category;
    public final float length, width, height, wheelbase;
    public final List<Wheel> wheels = new ArrayList<>();
    public final List<Vec3> seats = new ArrayList<>();
    public final List<Door> doors = new ArrayList<>();
    public final List<Vec3> beams = new ArrayList<>();
    public final List<float[]> plates = new ArrayList<>(); // pos xyz, normal xyz, w, h
    public final List<Dial> dials = new ArrayList<>();
    public float[] steerPivot = {0.4f, 0.9f, 0.5f}, steerAxis = {0, 0.4f, -0.9f};
    public float[] cluster; // center xyz, right xyz, up xyz, w, h
    public float[] filler = {-1f, 0.85f, -1.5f};
    public final float maxSpeedKmh, accel, brake, mass, fuelCapacity;
    public final int seatCount, spawnWeight;
    public final boolean electric, siren, beacons;
    public final String engineType, horn, clusterStyle, screenStyle;
    public final int idleRpm, driveRpm, redRpm, cylinders, dashIndex;
    public final boolean diesel;
    public final int[] colors;
    public final int paint2;
    // motorcycles
    public final boolean bike;
    public final float riderLean, riderLeg, riderSpread, riderScale, backfire;
    public float[] grips = {0.3f, 1.1f, 0.3f};
    public final List<float[]> exhausts = new ArrayList<>(); // pos xyz, dir xyz
    // Blockbench pipeline: own texture, customisation catalog, gear lever, pop-up lamps, parking sensor
    public String texture;
    public float[] matcap;
    public final java.util.Map<String, Integer> catalog = new java.util.LinkedHashMap<>();
    /** part names per slot for the tuning screen */
    public final java.util.Map<String, java.util.List<String>> catalogNames = new java.util.LinkedHashMap<>();
    public final List<List<float[]>> exhaustVariants = new ArrayList<>();
    public float[] shifterPivot;
    public String shifterType = "manual";
    public final java.util.Map<String, float[]> popups = new java.util.HashMap<>();
    public boolean screenSensor;
    public float grip = 0.85f;
    /** infotainment screen: center xyz, right xyz, up xyz, w, h (null = car has no screen) */
    public float[] screen;
    /** top-view outline for the park-assist screen: [t 0 rear..1 nose, half-width 0..1] */
    public final List<float[]> plan = new ArrayList<>(), cabinPlan = new ArrayList<>(), glassBands = new ArrayList<>();
    public float[] axlesT = {0.22f, 0.78f};
    public float planAspect = 0.4f;
    public String uiLayout = "tiles", uiBg = "#111214", uiAccent = "#3a8ee6", uiFg = "#e8e8ea", brandShape = "rect", brandText = "", brandColor = "#c8c8c8",
            brandName = "";
    public String make = "", modelName = "", categoryName = "", description = "";
    public int year;

    VehicleSpec(JsonObject o) {
        id = o.get("id").getAsString();
        name = o.get("name").getAsString();
        category = o.get("category").getAsString();
        length = f(o, "length", 4.5f);
        width = f(o, "width", 1.8f);
        height = f(o, "height", 1.5f);
        wheelbase = Math.max(1.5f, f(o, "wheelbase", 2.7f));
        for (JsonElement e : arr(o, "wheels")) {
            JsonObject w = e.getAsJsonObject();
            wheels.add(new Wheel(f(w, "x", 0), f(w, "y", 0.33f), f(w, "z", 0), f(w, "r", 0.33f), w.get("steer").getAsBoolean(), w.get("mirror").getAsBoolean()));
        }
        for (JsonElement e : arr(o, "seats")) {
            JsonArray a = e.getAsJsonArray();
            seats.add(new Vec3(a.get(0).getAsDouble(), a.get(1).getAsDouble(), a.get(2).getAsDouble()));
        }
        if (seats.isEmpty()) seats.add(new Vec3(0.4, 0.5, 0));
        if (o.has("doors")) {
            for (var en : o.getAsJsonObject("doors").entrySet()) {
                JsonObject d = en.getValue().getAsJsonObject();
                JsonArray h = d.getAsJsonArray("hinge");
                doors.add(new Door(en.getKey(), h.get(0).getAsFloat(), h.get(1).getAsFloat(), d.get("side").getAsInt(), d.get("kind").getAsString()));
            }
        }
        for (JsonElement e : arr(o, "beams")) {
            JsonArray a = e.getAsJsonArray();
            beams.add(new Vec3(a.get(0).getAsDouble(), a.get(1).getAsDouble(), a.get(2).getAsDouble()));
        }
        for (JsonElement e : arr(o, "plates")) {
            JsonObject p = e.getAsJsonObject();
            JsonArray pos = p.getAsJsonArray("pos"), n = p.getAsJsonArray("normal");
            plates.add(new float[]{pos.get(0).getAsFloat(), pos.get(1).getAsFloat(), pos.get(2).getAsFloat(), n.get(0).getAsFloat(), n.get(1).getAsFloat(),
                    n.get(2).getAsFloat(), f(p, "w", 0.52f), f(p, "h", 0.12f)});
        }
        if (o.has("steer")) {
            JsonObject s = o.getAsJsonObject("steer");
            steerPivot = vec(s.getAsJsonArray("pivot"));
            steerAxis = vec(s.getAsJsonArray("axis"));
        }
        if (o.has("cluster")) {
            JsonObject c = o.getAsJsonObject("cluster");
            float[] ce = vec(c.getAsJsonArray("center")), r = vec(c.getAsJsonArray("right")), u = vec(c.getAsJsonArray("up"));
            cluster = new float[]{ce[0], ce[1], ce[2], r[0], r[1], r[2], u[0], u[1], u[2], f(c, "w", 0.36f), f(c, "h", 0.18f)};
        }
        if (o.has("filler")) filler = vec(o.getAsJsonArray("filler"));
        maxSpeedKmh = f(o, "maxSpeed", 180);
        accel = f(o, "accel", 3);
        brake = f(o, "brake", 8);
        mass = f(o, "mass", 1500);
        fuelCapacity = f(o, "fuel", 60);
        seatCount = seats.size();
        spawnWeight = o.has("spawnWeight") ? o.get("spawnWeight").getAsInt() : 5;
        electric = o.has("electric") && o.get("electric").getAsBoolean();
        siren = o.has("siren") && o.get("siren").getAsBoolean();
        beacons = o.has("beacons") && o.get("beacons").getAsBoolean();
        horn = o.has("horn") ? o.get("horn").getAsString() : "car";
        JsonObject eng = o.has("engine") ? o.getAsJsonObject("engine") : new JsonObject();
        engineType = eng.has("type") ? eng.get("type").getAsString() : "i4_petrol";
        idleRpm = eng.has("idle") ? eng.get("idle").getAsInt() : 800;
        driveRpm = eng.has("drive") ? eng.get("drive").getAsInt() : 2800;
        cylinders = eng.has("cyl") ? eng.get("cyl").getAsInt() : 4;
        diesel = eng.has("diesel") && eng.get("diesel").getAsBoolean();
        JsonObject dash = o.has("dash") ? o.getAsJsonObject("dash") : new JsonObject();
        clusterStyle = dash.has("cluster_style") ? dash.get("cluster_style").getAsString() : "analog_modern";
        screenStyle = dash.has("screen_style") ? dash.get("screen_style").getAsString() : "nav_blue";
        dashIndex = dash.has("idx") ? dash.get("idx").getAsInt() : 0;
        int red = 6500;
        if (dash.has("dials")) {
            for (JsonElement e : dash.getAsJsonArray("dials")) {
                JsonObject d = e.getAsJsonObject();
                String k = d.get("kind").getAsString();
                int col = d.has("color") ? d.get("color").getAsInt() : 0xFF3020;
                dials.add(new Dial(k, f(d, "cx", 0), f(d, "cy", 0), f(d, "r", 0), f(d, "a0", 225), f(d, "a1", -45), f(d, "max", 1),
                        f(d, "x", 0), f(d, "y", 0), f(d, "w", 0), f(d, "h", 0), f(d, "size", 0.1f), col));
                if (k.startsWith("rpm")) red = (int) (f(d, "max", 7000) * 0.85f);
            }
        }
        redRpm = Math.max(driveRpm + 500, red);
        JsonArray cs = arr(o, "colors");
        colors = new int[Math.max(1, cs.size())];
        colors[0] = 0xB0121B;
        for (int i = 0; i < cs.size(); i++) colors[i] = Integer.parseInt(cs.get(i).getAsString().substring(1), 16);
        bike = o.has("bike") && o.get("bike").getAsBoolean();
        JsonObject rd = o.has("rider") ? o.getAsJsonObject("rider") : new JsonObject();
        riderLean = f(rd, "lean", 0);
        riderLeg = f(rd, "leg", 0);
        riderSpread = f(rd, "spread", 0.15f);
        riderScale = f(rd, "scale", 0.92f);
        backfire = f(o, "backfire", 0);
        if (o.has("grips")) grips = vec(o.getAsJsonArray("grips"));
        for (JsonElement e : arr(o, "exhausts")) {
            JsonArray a = e.getAsJsonArray();
            float[] x = new float[6];
            for (int i = 0; i < 6; i++) x[i] = a.get(i).getAsFloat();
            exhausts.add(x);
        }
        paint2 = o.has("paint2") ? Integer.parseInt(o.get("paint2").getAsString().substring(1), 16) : 0xF2F2F2;
        if (o.has("texture")) texture = o.get("texture").getAsString();
        if (o.has("matcap")) matcap = vec(o.getAsJsonArray("matcap"));
        if (o.has("catalog")) for (var en : o.getAsJsonObject("catalog").entrySet()) {
            catalog.put(en.getKey(), en.getValue().getAsJsonArray().size());
            java.util.List<String> nm = new java.util.ArrayList<>();
            for (JsonElement it : en.getValue().getAsJsonArray()) nm.add(it.isJsonObject() && it.getAsJsonObject().has("name") ? it.getAsJsonObject().get("name").getAsString() : "?");
            catalogNames.put(en.getKey(), nm);
        }
        for (JsonElement e : arr(o, "exhaust_variants")) {
            List<float[]> l = new ArrayList<>();
            for (JsonElement t : e.getAsJsonArray()) l.add(vec(t.getAsJsonArray()));
            exhaustVariants.add(l);
        }
        if (o.has("shifter")) {
            JsonObject sh = o.getAsJsonObject("shifter");
            shifterPivot = vec(sh.getAsJsonArray("pivot"));
            if (sh.has("type")) shifterType = sh.get("type").getAsString();
        }
        if (o.has("popups")) for (var en : o.getAsJsonObject("popups").entrySet()) {
            JsonObject pp = en.getValue().getAsJsonObject();
            float[] pv = vec(pp.getAsJsonArray("pivot"));
            popups.put(en.getKey(), new float[]{pv[0], pv[1], f(pp, "angle", -62)});
        }
        grip = f(o, "grip", 0.85f);
        if (o.has("infotainment")) {
            JsonObject sc = o.getAsJsonObject("infotainment");
            float[] c = vec(sc.getAsJsonArray("center")), r = vec(sc.getAsJsonArray("right")), u = vec(sc.getAsJsonArray("up"));
            screen = new float[]{c[0], c[1], c[2], r[0], r[1], r[2], u[0], u[1], u[2], f(sc, "w", 0.2f), f(sc, "h", 0.12f)};
            uiLayout = sc.get("layout").getAsString();
            uiBg = sc.get("bg").getAsString();
            uiAccent = sc.get("accent").getAsString();
            uiFg = sc.get("fg").getAsString();
            JsonObject b = sc.getAsJsonObject("brand");
            brandShape = b.get("shape").getAsString();
            brandText = b.get("text").getAsString();
            brandColor = b.get("color").getAsString();
            brandName = b.get("name").getAsString();
            if (sc.has("plan")) {
                for (JsonElement e : sc.getAsJsonArray("plan")) plan.add(vec(e.getAsJsonArray()));
                for (JsonElement e : sc.getAsJsonArray("cabin")) cabinPlan.add(vec(e.getAsJsonArray()));
                for (JsonElement e : sc.getAsJsonArray("glass")) glassBands.add(vec(e.getAsJsonArray()));
                axlesT = vec(sc.getAsJsonArray("axles"));
                planAspect = f(sc, "aspect", 0.4f);
            }
        }
        screenSensor = o.has("screen_sensor") && o.get("screen_sensor").getAsBoolean();
        if (o.has("make")) make = o.get("make").getAsString();
        if (o.has("model")) modelName = o.get("model").getAsString();
        if (o.has("category_name")) categoryName = o.get("category_name").getAsString();
        if (o.has("description")) description = o.get("description").getAsString();
        if (o.has("year")) year = o.get("year").getAsInt();
    }

    /** Exhaust tips of the fitted exhaust variant. */
    public List<float[]> exhaustsFor(int variant) {
        if (variant >= 0 && variant < exhaustVariants.size()) return exhaustVariants.get(variant);
        return exhausts;
    }

    public boolean isHeavy() {
        return category.equals("truck") || category.equals("bus");
    }

    public boolean beepsWhenReversing() {
        return category.equals("truck") || category.equals("van") || category.equals("bus");
    }

    private static float f(JsonObject o, String k, float def) {
        return o.has(k) && !o.get(k).isJsonNull() ? o.get(k).getAsFloat() : def;
    }

    private static JsonArray arr(JsonObject o, String k) {
        return o.has(k) && o.get(k).isJsonArray() ? o.getAsJsonArray(k) : new JsonArray();
    }

    private static float[] vec(JsonArray a) {
        float[] r = new float[a.size()];
        for (int i = 0; i < r.length; i++) r[i] = a.get(i).getAsFloat();
        return r;
    }
}
